SELECT s.canonical_smiles, m.chembl_id AS molecule_chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units FROM activities act JOIN molecule_dictionary m ON m.molregno = act.molregno JOIN compound_structures s ON s.molregno = m.molregno JOIN assays a ON a.assay_id = act.assay_id WHERE a.chembl_id = 'CHEMBL1217643' AND act.standard_relation = '=' AND act.standard_value IS NOT NULL AND act.standard_relation IS NOT NULL ORDER BY s.canonical_smiles, m.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units
